/// <summary>
/// Parameter data contract for importing files from Azure containers
/// </summary>
[DataContract]
class OMGInboundDataContract_AzureContainer extends OMGInboundDataContract_Azure
{
    OMGAzureSourceContainer     sourceContainer;
    OMGAzureArchiveContainer    archiveContainer;


}

Method.Source:
[DataMember, OMGAzureContainerField, SysOperationDisplayOrder('3')]
public OMGAzureSourceContainer parmSourceContainer(OMGAzureSourceContainer _sourceContainer = sourceContainer)
{
    sourceContainer = _sourceContainer;
    return sourceContainer;
}

[DataMember, OMGAzureContainerField, OMGArchiveDirectory, SysOperationDisplayOrder('4')]
public OMGAzureArchiveContainer parmArchiveContainer(OMGAzureArchiveContainer _archiveContainer = archiveContainer)
{
    archiveContainer = _archiveContainer;
    return archiveContainer;
}

/// <summary>
/// The caption used on the dialog
/// </summary>
/// <returns>A descriptive text</returns>
public Description dialogCaption()
{
    return "@OMG:ImportFromAzureContainer";
}
